<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAccountPreferences } from '../preferences/store'
import { defaultSidebar, type Workspace } from '../preferences/schema'
import { navigationLabel } from '../preferences/labels'
const props=defineProps<{workspace?:Workspace}>()
const store=useAccountPreferences(),selected=ref<Workspace>(props.workspace || 'timer')
const groups=computed(()=>selected.value==='timer'?[['primary','常用分组'],['tools','工具分组'],['subjects','科目分组']]:[['primary','常用分组'],['tools','工具分组']])
const config=computed(()=>store.values[`sidebar.${selected.value}`])
function update(patch:Partial<typeof config.value>){store.set(`sidebar.${selected.value}`,{...config.value,...patch})}
function visible(id:string,on:boolean){update({hidden:on?config.value.hidden.filter(value=>value!==id):[...config.value.hidden,id]})}
function move(id:string,delta:number){const order=[...config.value.order],index=order.indexOf(id),to=index+delta;if(to<0||to>=order.length)return;[order[index],order[to]]=[order[to]!,order[index]!];update({order})}
function collapsed(id:string,on:boolean){update({collapsed_groups:on?[...config.value.collapsed_groups,id]:config.value.collapsed_groups.filter(value=>value!==id)})}
</script>
<template><section class="sidebar-customization" aria-labelledby="sidebar-settings-heading"><header><h2 id="sidebar-settings-heading">侧栏布局</h2><label>学习空间<select v-model="selected" aria-label="编辑侧栏所属空间"><option value="timer">Learning OS</option><option value="drill">Drill</option><option value="ei">EI · 892</option></select></label></header><p>勾选显示在侧栏，取消后仍可从“更多工具”进入。使用上下按钮排序，设置与工作区入口始终保留。</p><ol><li v-for="(id,index) in config.order" :key="id"><label><input type="checkbox" :checked="!config.hidden.includes(id)" @change="visible(id,($event.target as HTMLInputElement).checked)"/><span>{{ navigationLabel(id,store.values.language) }}</span><small>{{ config.hidden.includes(id)?'More':'侧栏' }}</small></label><div><button type="button" class="ui-icon-button" :disabled="index===0" :aria-label="`上移 ${navigationLabel(id,store.values.language)}`" @click="move(id,-1)">↑</button><button type="button" class="ui-icon-button" :disabled="index===config.order.length-1" :aria-label="`下移 ${navigationLabel(id,store.values.language)}`" @click="move(id,1)">↓</button></div></li></ol><div class="sidebar-group-settings"><label v-for="[id,label] in groups" :key="id"><input type="checkbox" :checked="config.collapsed_groups.includes(id!)" @change="collapsed(id!,($event.target as HTMLInputElement).checked)"/>默认折叠{{ label }}</label></div><button type="button" class="ui-button ui-button--secondary" @click="store.set(`sidebar.${selected}`,defaultSidebar(selected))">恢复默认布局</button></section></template>
<style scoped>.sidebar-customization{min-width:0}.sidebar-customization header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.sidebar-customization h2{font-size:17px;margin:0}.sidebar-customization header label{display:flex;align-items:center;gap:8px;font-size:13px}.sidebar-customization select{font:inherit;min-height:44px;max-width:100%;background:var(--surface-subtle);border:0;color:var(--text-primary);padding:8px}.sidebar-customization p{font-size:13px;line-height:1.6;color:var(--text-secondary)}ol{list-style:none;padding:0;margin:16px 0}li{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:52px;border-bottom:1px solid var(--border-subtle)}li>label{display:flex;align-items:center;gap:12px;flex:1;min-width:0;min-height:44px;font-size:14px;cursor:pointer}li>label>span{overflow-wrap:anywhere}input{width:18px;height:18px;flex:none;accent-color:var(--accent-solid)}small{font-size:12px;color:var(--text-secondary);margin-left:auto}li>div{display:flex;flex:none}.ui-icon-button{width:44px;height:44px}.sidebar-group-settings{display:grid;gap:8px;margin:16px 0}.sidebar-group-settings label{display:flex;align-items:center;gap:8px;min-height:44px;font-size:13px}.ui-button{min-height:44px}</style>
